prog = '''def transform(grid):
    """Complete partial shapes: halves of shapes are vertically mirrored
    across horizontal separator rows. A lone half is filled in the direction
    where its partner belongs; direction is decided by matching the half
    against complete shapes in the same band row (exact or horizontally
    mirrored across a vertical separator), defaulting to downward fill."""
    h, w = len(grid), len(grid[0])
    hseps = find_seps(grid)
    vseps = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]
    bands = bands_of(hseps, h)
    strips = strips_of(vseps, w)

    def strip_of(c):
        for i, (a, b) in enumerate(strips):
            if a <= c <= b:
                return i
        return None

    def band_of(r):
        for i, (a, b) in enumerate(bands):
            if a <= r <= b:
                return i

    def mirror_targets(cells, s):
        mir = [(2 * s - r, c, v) for r, c, v in cells]
        if any(not (0 <= r < h) for r, _, _ in mir):
            return 'oob', mir
        if all(grid[r][c] == v for r, c, v in mir):
            st = 'complete'
        elif all(grid[r][c] in (0, v) for r, c, v in mir):
            st = 'fill'
        else:
            st = 'conflict'
        return st, mir

    halves = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == 0 or r in hseps or c in vseps:
                continue
            halves.setdefault((band_of(r), strip_of(c)), []).append((r, c, v))

    partner = {}
    for key, cells in halves.items():
        bi, si = key
        a, b = bands[bi]
        if si is None:
            continue
        for d, s in (('up', a - 1), ('down', b + 1)):
            st, mir = mirror_targets(cells, s)
            if st == 'complete':
                partner[key] = d

    fills = []
    for key, cells in halves.items():
        bi, si = key
        a, b = bands[bi]
        if si is None or key in partner:
            continue
        opts = []
        for d, s in (('up', a - 1), ('down', b + 1)):
            st, mir = mirror_targets(cells, s)
            if st == 'fill':
                opts.append((d, mir))
        if not opts:
            continue
        if len(opts) == 1:
            fills.append(opts[0][1])
            continue
        direction = None
        for k2, cells2 in halves.items():
            if k2[0] != bi or k2[1] == si or k2[1] is None or k2 not in partner:
                continue
            (a1, b1), (a2, b2) = strips[si], strips[k2[1]]
            if b1 - a1 != b2 - a2:
                continue
            def pat(cs, left):
                return sorted(((r - a), (c - left)) for r, c, v in cs)
            p1 = pat(cells, strips[si][0])
            p2 = pat(cells2, strips[k2[1]][0])
            wd = b1 - a1 + 1
            p2m = sorted(((r, wd - 1 - c) for r, c in p2))
            if p1 == p2 or p1 == p2m:
                direction = partner[k2]
                break
        if direction is None:
            direction = 'down'
        for d, mir in opts:
            if d == direction:
                fills.append(mir)

    out = [row[:] for row in grid]
    for mir in fills:
        for r, c, v in mir:
            if out[r][c] == 0:
                out[r][c] = v
    return out


def find_seps(g):
    h, w = len(g), len(g[0])
    return [r for r in range(h) if g[r][0] != 0 and all(g[r][c] == g[r][0] for c in range(w))]


def bands_of(seps, h):
    bs = []
    start = 0
    for s in seps + [h]:
        if s - 1 >= start:
            bs.append((start, s - 1))
        start = s + 1
    return bs


def strips_of(vseps, w):
    ss = []
    start = 0
    for s in vseps + [w]:
        if s - 1 >= start:
            ss.append((start, s - 1))
        start = s + 1
    return ss
'''
